// illustrative (NOT in the repo): in-flight dedupe wrapped around Resolver.resolve
class DedupingResolver {
  private readonly inflight = new Map<string, Promise<Resolution>>();
  constructor(private readonly inner: Resolver) {}

  async resolve(name: string, type: number): Promise<Resolution> {
    const key = `${canonicalName(name)}|${type}`;
    let p = this.inflight.get(key);
    if (!p) {
      p = this.inner.resolve(name, type).finally(() => this.inflight.delete(key));
      this.inflight.set(key, p);
    }
    const r = await p;
    return { ...r, answers: r.answers.map((a) => ({ ...a })), authority: r.authority.map((a) => ({ ...a })) };
  }
}
